/**
 * Shared MapSVG post editor panel (Gutenberg sidebar + Classic metabox).
 *
 * Layout (inside a host ShadowRoot):
 *   [#mapsvg-preview] [#mapsvg-form-container]
 * Form is independent of the map — changing Map only reloads the preview.
 */

/**
 * @param {unknown} raw
 * @returns {Array<{id: string, title?: string, tableName?: string}>}
 */
function parseRegions(raw) {
  if (!raw || raw === "null") {
    return []
  }
  try {
    const parsed = typeof raw === "string" ? JSON.parse(raw) : raw
    return Array.isArray(parsed) ? parsed : []
  } catch (e) {
    return []
  }
}

/**
 * @param {unknown} raw
 * @returns {object|null}
 */
function parseLocation(raw) {
  if (!raw || raw === "null") {
    return null
  }
  try {
    const parsed = typeof raw === "string" ? JSON.parse(raw) : raw
    return parsed && typeof parsed === "object" ? parsed : null
  } catch (e) {
    return null
  }
}

/**
 * Prefer the last linked region’s map, then lastMapId from MapSVG options, then sole map.
 * @param {Array<{id?: string, tableName?: string}>} regions
 * @param {Array<{id: number}>} maps
 * @param {number|string|null|undefined} lastMapId
 * @returns {number|null}
 */
function deriveMapId(regions, maps, lastMapId) {
  if (Array.isArray(regions) && regions.length) {
    for (let i = regions.length - 1; i >= 0; i--) {
      const tableName = (regions[i] && regions[i].tableName) || ""
      const match = String(tableName).match(/^regions_(\d+)$/)
      if (match) {
        return parseInt(match[1], 10)
      }
    }
  }
  if (lastMapId != null && lastMapId !== "") {
    const id = Number(lastMapId)
    if (!Number.isNaN(id) && Array.isArray(maps) && maps.some((m) => Number(m.id) === id)) {
      return id
    }
  }
  if (Array.isArray(maps) && maps.length === 1) {
    return Number(maps[0].id)
  }
  return null
}

/**
 * WP wp_localize_script stringifies scalars ("0" / "1"). Treat those as booleans.
 * @param {unknown} value
 * @param {boolean} defaultValue
 * @returns {boolean}
 */
function localizeBool(value, defaultValue) {
  if (value === undefined || value === null || value === "") {
    return defaultValue
  }
  if (value === true || value === 1 || value === "1") {
    return true
  }
  if (value === false || value === 0 || value === "0" || value === "false") {
    return false
  }
  const asNumber = Number(value)
  if (!Number.isNaN(asNumber)) {
    return asNumber !== 0
  }
  return Boolean(value)
}

/**
 * Strip front-end chrome / DB object loading. Map itself must not create a shadowRoot —
 * the metabox host already provides one.
 * @param {object} map
 * @param {{ regionSupport?: boolean }} opts
 */
function applyPostEditorMapOptions(map, opts) {
  map.options.multiSelect = !!opts.regionSupport
  map.options.useShadowRoot = false

  if (!map.options.filters) {
    map.options.filters = {}
  }
  map.options.filters.on = false
  map.options.filters.hide = true

  if (!map.options.menu) {
    map.options.menu = {}
  }
  map.options.menu.on = false
  map.options.menu.hideOnMobile = false

  if (!map.options.database) {
    map.options.database = {}
  }
  map.options.database.on = false
  map.options.database.loadOnStart = false

  if (map.options.layout?.mountMode === "tree") {
    // The editor selects locations, not the App's page chrome. Keep Query bindings
    // while projecting only the Map into a full-width, independent editor slot.
    map.options.nodes = [
      { id: "PostEditorMap", type: "slot", title: "Map", settings: {}, children: ["map"] },
      { id: "map", type: "map", title: "Map", settings: {}, children: [] },
      { id: "body", type: "body", title: "Body", settings: {}, children: [] },
    ]
    map.options.scenes = Array.from(map.options.scenes || []).map(page => ({ ...page, rootNodeId: "PostEditorMap", bodyNodeId: "body" }))
    const grid = [{ id: "PostEditorMap", x: 0, y: 0, w: 12, h: 1 }]
    map.options.layout = { ...map.options.layout, gap: 0, grids: { desktop: grid, tablet: grid, mobile: grid } }
  }

  if (!map.options.containers) {
    map.options.containers = {}
  }
  ;["leftSidebar", "rightSidebar", "header", "footer"].forEach((key) => {
    if (!map.options.containers[key]) {
      map.options.containers[key] = {}
    }
    map.options.containers[key].on = false
  })

  if (!map.options.actions) {
    map.options.actions = {}
  }
  if (!map.options.actions.region) {
    map.options.actions.region = {}
  }
  if (!map.options.actions.region.click) {
    map.options.actions.region.click = {}
  }
  Object.assign(map.options.actions.region.click, {
    showDetails: false,
    showPopover: false,
    goToLink: false,
    showAnotherMap: false,
    filterDirectory: false,
    zoom: false,
  })
  if (!map.options.actions.marker) {
    map.options.actions.marker = {}
  }
  if (!map.options.actions.marker.click) {
    map.options.actions.marker.click = {}
  }
  Object.assign(map.options.actions.marker.click, {
    showDetails: false,
    showPopover: false,
    goToLink: false,
    filterDirectory: false,
    zoom: false,
  })
}

/**
 * @param {object} map
 */
function clearLoadedMapData(map) {
  try {
    if (map.markers && typeof map.markers.forEach === "function") {
      const markers = []
      map.markers.forEach((m) => markers.push(m))
      markers.forEach((m) => {
        try {
          map.markerDelete(m)
        } catch (e) {
          // ignore
        }
      })
    }
  } catch (e) {
    // ignore
  }

  try {
    if (map.objects && typeof map.objects.clear === "function") {
      map.objects.clear()
    } else if (map.objects && Array.isArray(map.objects)) {
      map.objects.length = 0
    }
  } catch (e) {
    // ignore
  }

  try {
    if (map.controllers && map.controllers.filters && map.controllers.filters.destroy) {
      map.controllers.filters.destroy()
      map.controllers.filters = null
    }
  } catch (e) {
    // ignore
  }

  try {
    if (map.containers && map.containers.filters) {
      jQuery(map.containers.filters).empty().hide()
    }
  } catch (e) {
    // ignore
  }
}

/**
 * @param {object} config
 * @param {string|HTMLElement} config.host - Metabox/sidebar host; gets an open ShadowRoot
 * @param {() => string|null|undefined} config.getLocation
 * @param {(value: string|null) => void} config.setLocation
 * @param {() => string|null|undefined} config.getRegions
 * @param {(value: string|null) => void} config.setRegions
 * @param {object} [config.params]
 * @param {boolean} [config.classicLayout]
 * @returns {{ destroy: () => void, reload: () => void }}
 */
export function initMapSvgPostEditorPanel(config) {
  const params = config.params || window.mapsvgBackendParams || {}
  const maps = Array.isArray(params.maps) ? params.maps : []
  const markerSupport = localizeBool(params.markerSupport, true)
  const regionSupport = localizeBool(params.regionSupport, false)
  const classicLayout = !!config.classicLayout

  const hostEl =
    typeof config.host === "string" ? document.getElementById(config.host) : config.host

  let shadowRoot = null
  let previewEl = null
  let formContainerEl = null
  let mapsvg = null
  let formBuilder = null
  let locationCopy = null
  let selectedMapId = null
  let syncingRegions = false
  let destroyed = false
  let ignoreMapSelectChange = false

  window.mapsvgAdmin = {
    getData: () => ({
      options: params,
    }),
  }

  function persistLocation(value) {
    if (!value) {
      config.setLocation(null)
      return
    }
    config.setLocation(JSON.stringify(value))
  }

  function persistRegions(value) {
    if (!value || (Array.isArray(value) && value.length === 0)) {
      config.setRegions(null)
      return
    }
    config.setRegions(JSON.stringify(value))
  }

  function getPluginRootUrl() {
    if (window.mapsvg && window.mapsvg.routes && window.mapsvg.routes.root) {
      return String(window.mapsvg.routes.root).replace(/\/?$/, "/")
    }
    return "/"
  }

  function getAssetVersion() {
    const styles = (window.mapsvg && window.mapsvg.styles) || []
    if (styles.length && styles[0].version) {
      return styles[0].version
    }
    return String(Date.now())
  }

  function injectHostShadowStyles() {
    if (!shadowRoot || shadowRoot.querySelector("[data-mapsvg-post-editor-css]")) {
      return
    }
    const root = getPluginRootUrl()
    const version = getAssetVersion()
    const files = [
      "css/mapsvg-admin-bundle.css",
      "js/mapsvg/FormBuilder/form.css",
      "css/mapsvg-gutenberg.css",
    ]
    files.forEach((rel) => {
      const link = document.createElement("link")
      link.rel = "stylesheet"
      link.href = root + rel + "?ver=" + encodeURIComponent(version)
      link.setAttribute("data-mapsvg-post-editor-css", "1")
      shadowRoot.appendChild(link)
    })
  }

  /**
   * Attach open shadow to host and build preview + form layout.
   */
  function ensureHostLayout() {
    if (!hostEl) {
      return false
    }
    if (!hostEl.shadowRoot) {
      shadowRoot = hostEl.attachShadow({ mode: "open" })
    } else {
      shadowRoot = hostEl.shadowRoot
    }

    let layout = shadowRoot.querySelector(".mapsvg-location-layout")
    if (!layout) {
      shadowRoot.innerHTML = ""
      injectHostShadowStyles()

      layout = document.createElement("div")
      layout.className =
        "mapsvg-location-layout" +
        (classicLayout ? " mapsvg-location-layout--classic" : " mapsvg-location-layout--sidebar")

      previewEl = document.createElement("div")
      previewEl.id = "mapsvg-preview"

      formContainerEl = document.createElement("div")
      formContainerEl.id = "mapsvg-form-container"

      layout.appendChild(previewEl)
      layout.appendChild(formContainerEl)
      shadowRoot.appendChild(layout)
    } else {
      injectHostShadowStyles()
      previewEl = shadowRoot.querySelector("#mapsvg-preview")
      formContainerEl = shadowRoot.querySelector("#mapsvg-form-container")
    }

    return !!(previewEl && formContainerEl)
  }

  /**
   * Fresh map mount node inside #mapsvg-preview (Map.destroy may wipe previous node).
   * @returns {HTMLElement|null}
   */
  function resetMapMountEl() {
    if (!previewEl) {
      return null
    }
    previewEl.innerHTML = ""
    const el = document.createElement("div")
    el.id = "mapsvg"
    previewEl.appendChild(el)
    return el
  }

  function createLocationCopy(locationFieldData) {
    if (!locationFieldData || !mapsvg) {
      return null
    }
    const location = new window.mapsvg.location(locationFieldData)
    const markerCopy = new window.mapsvg.marker({
      location,
      mapsvg,
    })
    mapsvg.markerAdd(markerCopy)
    return location
  }

  function watchMarkerChanges(locationFormElement, location) {
    if (location && location.marker) {
      location.marker.events.on("change", () => {
        if (location.marker.isMoving()) {
          return false
        }
        locationFormElement.setValue(location.getData())
        locationFormElement.triggerChanged()
      })
    }
  }

  function destroyMapOnly() {
    locationCopy = null
    if (mapsvg) {
      try {
        mapsvg.events.off("click.region", onMapRegionClick)
      } catch (e) {
        // ignore
      }
      try {
        mapsvg.destroy()
      } catch (e) {
        // ignore
      }
    }
    mapsvg = null
    if (previewEl) {
      previewEl.innerHTML = ""
    }
  }

  function destroyFormOnly() {
    ignoreMapSelectChange = true
    if (formBuilder && typeof formBuilder.destroy === "function") {
      try {
        formBuilder.destroy()
      } catch (e) {
        // ignore
      }
    }
    formBuilder = null
    if (formContainerEl) {
      formContainerEl.innerHTML = ""
    }
    setTimeout(() => {
      ignoreMapSelectChange = false
    }, 0)
  }

  function destroyAll() {
    destroyFormOnly()
    destroyMapOnly()
  }

  /**
   * Persist last chosen map per post type in MapSVG options (for new posts).
   * @param {number} mapId
   */
  function rememberLastMap(mapId) {
    if (!mapId || !params.postType) {
      return
    }
    if (!window.mapsvg || !window.mapsvg.server || !window.mapsvg.routes) {
      return
    }
    const lastMaps = Object.assign({}, params.lastMaps || {})
    lastMaps[params.postType] = mapId
    params.lastMaps = lastMaps
    params.lastMapId = mapId
    try {
      const server = new window.mapsvg.server(window.mapsvg.routes.api)
      server.post("options", {
        options: JSON.stringify({ post_editor_last_map: lastMaps }),
      })
    } catch (e) {
      // ignore
    }
  }

  function needsMapSelectField() {
    return regionSupport && maps.length > 1
  }

  function buildSchemaFields() {
    const fields = []

    if (regionSupport && maps.length === 0) {
      return fields
    }

    if (needsMapSelectField()) {
      fields.push({
        type: "select",
        name: "mapId",
        label: "Map",
        options: [
          { label: "Select a map…", value: "" },
          ...maps.map((map) => ({
            label: map.title || `Map #${map.id}`,
            value: String(map.id),
          })),
        ],
      })
    }

    if (markerSupport) {
      fields.push({
        type: "location",
        name: "location",
        label: "Location",
      })
    }

    if (regionSupport && selectedMapId) {
      fields.push({
        type: "relation",
        name: "regions",
        label: "Regions",
        multiselect: true,
      })
    }

    return fields
  }

  function onMapSelectChanged(rawValue) {
    if (ignoreMapSelectChange || destroyed) {
      return
    }
    const nextId = rawValue ? parseInt(String(rawValue), 10) : null
    const normalized = nextId && !Number.isNaN(nextId) ? nextId : null
    if (normalized === selectedMapId) {
      return
    }
    persistRegions(null)
    selectedMapId = normalized
    if (selectedMapId) {
      rememberLastMap(selectedMapId)
    }
    // Reload map only — form stays mounted until afterInit rebuilds region fields.
    setTimeout(() => {
      if (!destroyed) {
        loadMap()
      }
    }, 0)
  }

  function onMapRegionClick() {
    syncFormFromMapSelection()
  }

  function syncFormFromMapSelection() {
    if (!formBuilder || !mapsvg || syncingRegions) {
      return
    }
    const regionsFormElement = formBuilder.getFormElementByType("region")
    if (!regionsFormElement) {
      return
    }
    syncingRegions = true
    const ids = mapsvg.getSelected() || []
    regionsFormElement.setValue(ids, true)
    persistRegions(regionsFormElement.getData().value)
    syncingRegions = false
  }

  function syncMapFromFormSelection(regionObjects) {
    if (!mapsvg || syncingRegions) {
      return
    }
    syncingRegions = true
    mapsvg.deselectAllRegions()
    const tableName =
      mapsvg.regionsRepository && mapsvg.regionsRepository.getSchema
        ? mapsvg.regionsRepository.getSchema().name
        : `regions_${selectedMapId}`
    const ids = (regionObjects || [])
      .filter((r) => !r.tableName || r.tableName === tableName)
      .map((r) => r.id)
    ids.forEach((id) => {
      try {
        mapsvg.selectRegion(id, true)
      } catch (e) {
        // ignore missing
      }
    })
    syncingRegions = false
  }

  /**
   * Build / rebuild form in #mapsvg-form-container (independent of map lifecycle).
   * @param {object|null} map
   */
  function setupFormBuilder(map) {
    if (!formContainerEl) {
      return
    }

    // Location/Regions controls require a ready Map (schema, calibration and
    // templates). A detached initial FormBuilder races its replacement on load.
    if (!map) {
      if (regionSupport && maps.length === 0) formContainerEl.innerHTML = '<p class="description">No maps linked to this data source.</p>'
      return
    }

    destroyFormOnly()

    const locationData = parseLocation(config.getLocation())
    const regionsData = parseRegions(config.getRegions())
    const formData = {}

    if (needsMapSelectField()) {
      formData.mapId = selectedMapId ? String(selectedMapId) : ""
    }

    if (markerSupport && map && locationData) {
      const location = new window.mapsvg.location(locationData)
      const marker = new window.mapsvg.marker({
        location,
        mapsvg: map,
      })
      map.markerAdd(marker)
      formData.location = location.getData()

      if (map.options.googleMaps && map.options.googleMaps.on) {
        const coords = {
          lat: location.geoPoint.lat,
          lng: location.geoPoint.lng,
        }
        const zoomToMarker = () => {
          if (map.googleMaps && map.googleMaps.map) {
            map.googleMaps.map.setCenter(coords)
            map.googleMaps.map.setZoom(10)
          }
        }
        if (map.googleMaps && map.googleMaps.initialized) {
          zoomToMarker()
        } else {
          map.events.on("afterLoad.googleMaps", zoomToMarker)
          map.events.on("googleMapsLoaded", zoomToMarker)
        }
      }
    } else if (markerSupport && locationData) {
      formData.location = locationData
    }

    if (regionSupport && selectedMapId && regionsData.length) {
      formData.regions = regionsData
    }

    const fields = buildSchemaFields()
    if (!fields.length) {
      if (regionSupport && maps.length === 0) {
        formContainerEl.innerHTML =
          '<p class="description">No maps linked to this data source.</p>'
      }
      return
    }

    formContainerEl.innerHTML = ""

    formBuilder = new window.mapsvg.formBuilder({
      container: formContainerEl,
      schema: new window.mapsvg.schema({ fields }),
      showNames: false,
      editMode: false,
      filtersMode: false,
      scrollable: false,
      mapsvg: map,
      mediaUploader: null,
      data: formData,
      admin: null,
      closeOnSave: false,
      events: {
        init: () => {
          if (markerSupport && map) {
            map.hideMarkers()
            const locationFormElement = formBuilder.getFormElementByType("location")
            if (locationFormElement && locationFormElement.value) {
              locationCopy = createLocationCopy(locationFormElement.value)
              if (locationCopy) {
                watchMarkerChanges(locationFormElement, locationCopy)
                map.setEditingMarker(locationCopy.marker)
              }
            }
            map.setMarkerEditHandler((location) => {
              if (locationCopy) {
                map.markerDelete(locationCopy.marker)
              }
              locationCopy = location
              map.setEditingMarker(locationCopy.marker)
              if (locationFormElement) {
                locationFormElement.setValue(location.getData())
                locationFormElement.triggerChanged()
                watchMarkerChanges(locationFormElement, locationCopy)
              }
            })
          }

          if (regionSupport && selectedMapId && map) {
            const regionsFormElement = formBuilder.getFormElementByType("region")
            if (regionsFormElement) {
              syncMapFromFormSelection(regionsFormElement.getData().value || regionsData)
            }
          }
        },
        "delete.formElement": (event) => {
          const { formElement } = event.data
          if (formElement.type === "location" && locationCopy && map) {
            map.markerDelete(locationCopy.marker)
            locationCopy = null
            persistLocation(null)
          }
        },
        "change.formElement": (event) => {
          const { formElement, value } = event.data

          if (formElement.name === "mapId") {
            onMapSelectChanged(value)
            return
          }

          if (formElement.type === "location") {
            persistLocation(value || null)

            if (!mapsvg) {
              return
            }

            if (locationCopy) {
              if (
                value &&
                (locationCopy.geoPoint.lat != value.geoPoint.lat ||
                  locationCopy.geoPoint.lng != value.geoPoint.lng)
              ) {
                if (
                  mapsvg.options.googleMaps &&
                  mapsvg.options.googleMaps.on &&
                  mapsvg.googleMaps.map
                ) {
                  mapsvg.googleMaps.map.setCenter({
                    lat: value.geoPoint.lat,
                    lng: value.geoPoint.lng,
                  })
                  mapsvg.googleMaps.map.setZoom(17)
                }
              }
              mapsvg.markerDelete(locationCopy.marker)
              locationCopy = null
            }

            if (value) {
              locationCopy = new window.mapsvg.location(value)
              const marker = new window.mapsvg.marker({
                location: locationCopy,
                mapsvg,
              })
              mapsvg.markerAdd(locationCopy.marker)
              mapsvg.setEditingMarker(marker)
              watchMarkerChanges(formElement, locationCopy)
            }
          }

          if (
            formElement.type === "region" ||
            formElement.type === "relation" ||
            formElement.name === "regions"
          ) {
            if (syncingRegions) {
              return
            }
            persistRegions(value || [])
            syncMapFromFormSelection(value || [])
          }
        },
      },
    })
    formBuilder.init()
  }

  function getExternal(prefetch) {
    return {
      markerImages: params.markerImages || params.mapsvgMarkerImages || [],
      googleApiKey: params.googleApiKey,
      prefetch: !!prefetch,
      inBackend: false,
    }
  }

  function onMapReady(map) {
    mapsvg = map
    applyPostEditorMapOptions(mapsvg, { regionSupport })
    if (typeof mapsvg.setContainers === "function") {
      mapsvg.setContainers({
        leftSidebar: { on: false },
        rightSidebar: { on: false },
        header: { on: false },
        footer: { on: false },
      })
    }
    clearLoadedMapData(map)
    if (markerSupport) {
      mapsvg.setMarkersEditMode(true)
    }
    if (regionSupport && selectedMapId) {
      mapsvg.events.off("click.region", onMapRegionClick)
      mapsvg.events.on("click.region", onMapRegionClick)
    }
    // Rebuild form against the new map (regions list / marker binding).
    // Form container itself was never cleared by destroyMapOnly.
    setupFormBuilder(mapsvg)
  }

  function loadLocationOnlyMap() {
    const container = resetMapMountEl()
    if (!container) {
      return
    }

    const mapsPath = params.mapsPath || ""
    const source = params.googleApiKey
      ? mapsPath.replace(/\/?$/, "/") + "geo-calibrated/empty.svg"
      : mapsPath.replace(/\/?$/, "/") + "geo-calibrated/world.svg"

    const mapOptions = {
      source,
      useShadowRoot: false,
      filters: { on: false },
      fitMarkers: true,
      multiSelect: false,
      defaultMarkerImage: window.mapsvg.routes.root + "markers/_pin_default.png",
      containers: {
        header: { on: false },
        leftSidebar: { on: false },
        footer: { on: false },
        rightSidebar: { on: false },
      },
      googleMaps: {
        on: !!params.googleApiKey,
        apiKey: params.googleApiKey,
      },
      database: {
        on: false,
        loadOnStart: false,
        regionsTableName: "regions_0",
        objectsTableName: "objects_0",
      },
      events: {
        afterInit: (event) => {
          onMapReady(event.map)
        },
      },
    }

    new window.mapsvg.map(container, { options: mapOptions }, getExternal(false))
  }

  function loadMapById(mapId) {
    const container = resetMapMountEl()
    if (!container) {
      return
    }

    const map = new window.mapsvg.map(
      container,
      {
        id: mapId,
        options: {
          id: mapId,
          useShadowRoot: false,
          multiSelect: !!regionSupport,
          filters: { on: false },
          menu: { on: false, hideOnMobile: false },
          database: {
            on: false,
            loadOnStart: false,
          },
          containers: {
            header: { on: false },
            leftSidebar: { on: false },
            footer: { on: false },
            rightSidebar: { on: false },
          },
        },
      },
      getExternal(true),
    )

    map.events.on("beforeInit", () => {
      applyPostEditorMapOptions(map, { regionSupport })
    })

    map.events.once("afterInit", () => {
      onMapReady(map)
    })
  }

  /**
   * Reload map preview only — does not clear the form container first.
   */
  function loadMap() {
    if (destroyed) {
      return
    }
    if (!previewEl || !formContainerEl) {
      return
    }
    if (!window.mapsvg || !window.mapsvg.map) {
      return
    }

    destroyMapOnly()

    if (regionSupport && maps.length === 1 && !selectedMapId) {
      selectedMapId = Number(maps[0].id)
    }

    if (regionSupport && selectedMapId) {
      loadMapById(selectedMapId)
      return
    }

    if (markerSupport || (regionSupport && needsMapSelectField())) {
      loadLocationOnlyMap()
      return
    }

    if (regionSupport && maps.length === 0) {
      setupFormBuilder(null)
    }
  }

  function load() {
    if (!ensureHostLayout()) {
      return
    }
    // Form shell first (stays while map preview loads / reloads).
    if (!formBuilder) {
      setupFormBuilder(null)
    }
    loadMap()
  }

  selectedMapId = regionSupport
    ? deriveMapId(parseRegions(config.getRegions()), maps, params.lastMapId)
    : null
  load()

  return {
    reload: load,
    destroy: () => {
      destroyed = true
      destroyAll()
    },
  }
}
