import { initMapSvgPostEditorPanel } from "../shared/mapsvg-post-editor-panel.js"

function getHiddenValue(id) {
  const el = document.getElementById(id)
  if (!el || !el.value || el.value === "null") {
    return null
  }
  return el.value
}

function setHiddenValue(id, value) {
  const el = document.getElementById(id)
  if (!el) {
    return
  }
  el.value = value == null ? "" : value
}

function initMapClassicEditor() {
  const host = document.getElementById("mapsvg-location-host")
  if (!host) {
    return
  }

  initMapSvgPostEditorPanel({
    host,
    getLocation: () => getHiddenValue("mapsvg_location"),
    setLocation: (value) => setHiddenValue("mapsvg_location", value),
    getRegions: () => getHiddenValue("mapsvg_regions"),
    setRegions: (value) => setHiddenValue("mapsvg_regions", value),
    classicLayout: true,
  })
}

if (window.mapsvg && window.mapsvg.initialized) {
  initMapClassicEditor()
} else {
  window.addEventListener("mapsvgClientInitialized", initMapClassicEditor)
}
